import"./modulepreload-polyfill.js";document.getElementById(`btn-open-side-panel`).addEventListener(`click`,async()=>{let[e]=await chrome.tabs.query({active:!0,currentWindow:!0});if(!e?.id){console.error(`No active tab`);return}try{await chrome.tabCapture.getMediaStreamId({targetTabId:e.id}),await chrome.sidePanel.open({windowId:e.windowId})}catch(e){console.error(`getMediaStreamId Failed`,e)}});